    37	    if name == "/connect":
    38	        if len(arguments) > 1:
    39	            raise ValueError("Usage: /connect [username]")
    40	    elif name not in {"/disconnect", "/drop-connection", "/status", "/help", "/quit"}:
    41	        raise ValueError("Unknown command: use /help")
    42	    elif arguments:
    43	        raise ValueError(f"Usage: {name}")
