    15	}
    16	
    17	pub fn parse(line: &str) -> Result<Command, &'static str> {
    18	    let line = line.trim_start();
    19	    let (verb, arguments) = line.split_once(char::is_whitespace).unwrap_or((line, ""));
    20	    match verb {
    21	        "/connect" => {
    22	            let mut names = arguments.split_whitespace();
    23	            let name = names.next().map(str::to_owned);
    24	            if names.next().is_some() {
    25	                return Err("Usage: /connect [username]");
    26	            }
    27	            Ok(Command::Connect(name))
    28	        }
    29	        "/send" => {
    30	            let arguments = arguments.trim_start();
    31	            let (recipient, text) = arguments
    32	                .split_once(char::is_whitespace)
    33	                .ok_or("Usage: /send <recipient> <text>")?;
    34	            if recipient.is_empty() || text.trim().is_empty() {
    35	                return Err("Usage: /send <recipient> <text>");
    36	            }
    37	            Ok(Command::Send {
    38	                recipient: recipient.to_owned(),
    39	                text: text.to_owned(),
    40	            })
    41	        }
    42	        "/disconnect" if arguments.trim().is_empty() => Ok(Command::Disconnect),
    43	        "/drop-connection" if arguments.trim().is_empty() => Ok(Command::DropConnection),
    44	        "/status" if arguments.trim().is_empty() => Ok(Command::Status),
    45	        "/help" if arguments.trim().is_empty() => Ok(Command::Help),
    46	        "/quit" if arguments.trim().is_empty() => Ok(Command::Quit),
    47	        _ => Err("Unknown command. Use /help"),
    48	    }
    49	}
