    51	pub fn input() -> UnboundedReceiver<String> {
    52	    let (sender, receiver) = unbounded_channel();
    53	    // A dedicated reader lets /quit exit without waiting for another stdin read.
    54	    std::thread::spawn(move || {
    55	        for line in io::stdin().lock().lines() {
    56	            let Ok(line) = line else { break };
    57	            if sender.send(line).is_err() {
    58	                break;
    59	            }
    60	        }
    61	    });
    62	    receiver
    63	}
    64	
    65	pub fn output(message: &str) {
    66	    let mut stdout = io::stdout().lock();
    67	    let _ = writeln!(stdout, "{message}");
    68	    let _ = stdout.flush();
    69	}
    70	
    71	pub fn status(state: &ClientState) -> String {
    72	    let connection = match state.connection_state {
    73	        ConnectionState::Disconnected => "disconnected",
    74	        ConnectionState::Connecting => "connecting",
    75	        ConnectionState::Connected => "connected",
    76	    };
    77	    let session = match state.session_state {
    78	        SessionState::None => "none",
    79	        SessionState::LoginPending => "login pending",
    80	        SessionState::LoggedIn => "logged in",
    81	    };
    82	    let user = state.authenticated_user.as_ref().map_or("-", |u| &u.name);
    83	    let heartbeat = state
    84	        .last_heartbeat_at
    85	        .map_or_else(|| "never".into(), |time| time.to_rfc3339());
    86	    format!(
    87	        "Server: {}\nConnection: {connection}\nSession: {session}\nUser: {user}\nLast heartbeat: {heartbeat}",
    88	        state.server_url
    89	    )
    90	}
