     6	
     7	pub enum Command {
     8	    Connect(Option<String>),
     9	    Disconnect,
    10	    DropConnection,
    11	    Send { recipient: String, text: String },
    12	    Status,
    13	    Help,
    14	    Quit,
    15	}
    16	
    17	pub fn parse(line: &str) -> Result<Command, &'static str> {
    18	    let line = line.trim_start();
    19	    let (verb, arguments) = line.split_once(char::is_whitespace).unwrap_or((line, ""));
    20	    match verb {
    21	        "/connect" => {
    22	            let mut names = arguments.split_whitespace();
    23	            let name = names.next().map(str::to_owned);
    24	            if names.next().is_some() {
    25	                return Err("Usage: /connect [username]");
    26	            }
    27	            Ok(Command::Connect(name))
    28	        }
    29	        "/send" => {
    30	            let arguments = arguments.trim_start();
    31	            let (recipient, text) = arguments
    32	                .split_once(char::is_whitespace)
    33	                .ok_or("Usage: /send <recipient> <text>")?;
    34	            if recipient.is_empty() || text.trim().is_empty() {
    35	                return Err("Usage: /send <recipient> <text>");
    36	            }
    37	            Ok(Command::Send {
    38	                recipient: recipient.to_owned(),
    39	                text: text.to_owned(),
    40	            })
    41	        }
    42	        "/disconnect" if arguments.trim().is_empty() => Ok(Command::Disconnect),
    43	        "/drop-connection" if arguments.trim().is_empty() => Ok(Command::DropConnection),
    44	        "/status" if arguments.trim().is_empty() => Ok(Command::Status),
    45	        "/help" if arguments.trim().is_empty() => Ok(Command::Help),
    46	        "/quit" if arguments.trim().is_empty() => Ok(Command::Quit),
    47	        _ => Err("Unknown command. Use /help"),
    48	    }
    49	}
    50	
    51	pub fn input() -> UnboundedReceiver<String> {
    52	    let (sender, receiver) = unbounded_channel();
    53	    // A dedicated reader lets /quit exit without waiting for another stdin read.
    54	    std::thread::spawn(move || {
    55	        for line in io::stdin().lock().lines() {
    56	            let Ok(line) = line else { break };
    57	            if sender.send(line).is_err() {
    58	                break;
    59	            }
    60	        }
    61	    });
    62	    receiver
    63	}
    64	
    65	pub fn output(message: &str) {
    66	    let mut stdout = io::stdout().lock();
    67	    let _ = writeln!(stdout, "{message}");
    68	    let _ = stdout.flush();
    69	}
    70	
    71	pub fn status(state: &ClientState) -> String {
    72	    let connection = match state.connection_state {
    73	        ConnectionState::Disconnected => "disconnected",
    74	        ConnectionState::Connecting => "connecting",
    75	        ConnectionState::Connected => "connected",
    76	    };
    77	    let session = match state.session_state {
    78	        SessionState::None => "none",
    79	        SessionState::LoginPending => "login pending",
    80	        SessionState::LoggedIn => "logged in",
    81	    };
    82	    let user = state.authenticated_user.as_ref().map_or("-", |u| &u.name);
    83	    let heartbeat = state
    84	        .last_heartbeat_at
    85	        .map_or_else(|| "never".into(), |time| time.to_rfc3339());
    86	    format!(
    87	        "Server: {}\nConnection: {connection}\nSession: {session}\nUser: {user}\nLast heartbeat: {heartbeat}",
    88	        state.server_url
    89	    )
    90	}
